(function(){'use strict';
const K=ArtifactCampaignDeck,A=ArtifactCampaign,D=ArtifactCampaignData,I=ArtifactI18n,base=ARTIFACT_CARDS,all=Object.fromEntries([...base,...D.heroes,...D.units].map(c=>[c.key,c])),root=document.querySelector('#campaign'),sound=new ArtifactAudio();
const T=I.T,pick=I.pick,LANG=()=>I.lang();
let p=A.fresh(),game=null,view='map',focus=null,busy=false,message='',confirmKey=null,dialogue=0,noticeTimer;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const LANE_NAMES=[T('上路','Top'),T('中路','Mid'),T('下路','Bot')];
try{const saved=JSON.parse(localStorage.getItem(A.SAVE_KEY));if(saved){K.migrate(saved);if(!A.valid(saved))throw Error(T('存档版本或队伍数据无效','Save version or party data invalid'));p=K.migrate(saved);message=p.migrationNotice||'';if(p.battle){game=new A.CampaignGame(base);game.s=p.battle;view='map';}}}catch(e){message=T('未能读取剧情存档：','Could not read the campaign save: ')+e.message+T('。原始数据未覆盖，请导出备份后再开始。',' Original data was left untouched — export a backup before starting over.');}
function save(){p.battle=game?game.s:null;try{localStorage.setItem(A.SAVE_KEY,JSON.stringify(p));}catch(e){notify(T('存档失败，请立即使用“导出存档”备份。','Saving failed — use "Export save" to back up now.'));}}
function notify(t){document.querySelector('#notice').textContent=t;clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>document.querySelector('#notice').textContent='',4500);}
const button=(action,label,extra='')=>`<button data-act="${action}" ${extra}>${label}</button>`;
const name=k=>pick(all[k],'name')||k;
const art=k=>all[k]?.art||all.slark.art;
const who=k=>{const w=D.people[k];return w?(LANG()==='en'?w[1]:w[0]):k;};
const line=ln=>LANG()==='en'?(ln[2]??ln[1]):ln[1];
const sceneOf=st=>D.scene(st,p.scene||0);
const sceneBadge=st=>A.sceneCount(st)>1?` · ${T('第 '+(p.scene+1)+'/'+A.sceneCount(st)+' 幕','Scene '+(p.scene+1)+'/'+A.sceneCount(st))}`:'';
const RARITIES={Common:T('普通','Common'),Uncommon:T('非凡','Uncommon'),Rare:T('稀有','Rare'),Foe:T('敌方','Foe')};
const RULE_WARN={stone:[T('小小第一轮完全免疫伤害。先保护队伍，等待山心暴露。','Tiny is immune to all damage in the first round. Protect the party and wait for the mountain heart to show.')],web:[T('蜘蛛每两轮召来新的幼蛛。','The spider calls fresh broodlings every other round.')],mirror:[T('攻击法术会被折镜反射 2 点穿甲伤害。','Strike spells are reflected for 2 piercing damage by the mirror hall.')]};
const ELITE_WARN={veil:[T('魅影之纱：敌人攻击附带半额会心伤害——用护甲、缴械与残纱活过突袭。','Sisters of the Veil: enemy strikes carry bonus critical damage — survive with armor, disarm, and the remnant.')],trial:[T('龙族试炼：主将每轮回复 4 生命；龙蛋庇佑持蛋者 +2 护甲。','Dragonkin trial: the champion regenerates 4 each round; the egg grants its bearer +2 armor.')],rampage:[T('狂暴：敌将每轮攻击 +1。','Rampage: the enemy champion gains +1 attack each round.')]};
function top(){return `<header class="masthead"><a class="logo" href="index.html">A <span>ARTIFACT<small>${T('暗月残片 · 独立剧情','Dark Moon Shards · Solo Story')}</small></span></a><nav>${button('map',T('旅程','Journey'),view==='map'?'class="active"':'')}${button('party',T('同行者','Companions'),view==='party'?'class="active"':'')}${button('deck',T('因果牌组','Causality Deck'),view==='deck'?'class="active"':'')}${button('journal',T('见闻','Journal'),view==='journal'?'class="active"':'')}</nav><div class="tools">${button('audio',sound.enabled?'♫ '+T('声音','Sound'):'♪ '+T('静音','Muted'),`aria-label="${T('切换音乐音效','Toggle music and sound')}"`)}${button('export',T('导出存档','Export save'))}<label class="import">${T('导入','Import')}<input type="file" id="import" accept="application/json"></label></div></header>`;}
function metrics(){return `<div class="metrics"><span>${T('小鱼人','Slark')} <b>Lv.${p.stage+1}</b></span><span>${T('成长','Growth')} <b>+${p.growth.attack} ${T('攻','ATK')} / +${p.growth.health} ${T('血','HP')}</b></span><span>${T('共鸣','Resonance')} <b>${p.resonance}</b></span><span>${T('污名','Stigma')} <b>${p.stigma.join(' / ')}</b><small>${T('金钥匙 / 龙诗 / 羽毛','Golden Key / Dragon Poem / Feather')}</small></span><span>${T('旅费','Supplies')} <b>${p.gold}</b></span>${p.drill?`<span>${T('历练','Drill')} <b>${p.drill}</b></span>`:''}${p.forge?`<span>${T('潮汐刃','Tideblade')} <b>${T('已锻造','forged')}</b></span>`:''}${p.scepter?`<span>${T('神杖','The Scepter')} <b>${p.scepterUsed?T('已使用','spent'):T('可用 · 旅程限一次','ready · once per journey')}</b></span>`:''}</div>`;}
function pendingEvent(){return (D.events||[]).find(ev=>ev.after===p.stage-1&&!p.choices?.[ev.id]);}
function map(){if(game?.s.winner!==null&&game)return result();const ev=pendingEvent();if(ev)return event(ev);if(p.cardReward)return cardReward();if(p.stage>=D.stages.length)return ending();const st=D.stages[p.stage];return `<main class="atlas"><section class="prologue"><div><p class="eyebrow">DARK MOON SHARDS / ${String(p.stage+1).padStart(2,'0')} OF 18</p><h1>${T('暗月残片','Dark Moon Shards')}<span>${T('鱼人的潮汐',"the Fish-Person's Tide")}</span></h1><p class="motto">${T('海从不问你来处。','The sea never asks where you came from.')}<br>${T('但潮水，会带回你留下的一切。','But the tide brings back everything you left behind.')}</p>${metrics()}<div class="hero-actions">${button(game?'resume':'story',game?T('继续战斗','Resume battle'):T('启程 · ','Embark · ')+pick(st,'title'),'class="primary"')}${button('party',T('整理队伍 →','Muster the party →'))}</div><p class="fine">${T('独立存档 · 1–3 条战线 · 每战最多 5 名英雄','Separate save · 1–3 lanes · up to 5 heroes per battle')}<br>${T('小鱼人必须出战。阵亡英雄本关不复活，关后休整恢复。','Slark must fight. Fallen heroes do not revive mid-stage; rest restores them.')}</p></div><div class="moon-art"><div class="moon"></div><img src="${art('slark')}" alt="${T('小鱼人斯拉克','Slark the fish-person')}"><span>${T('“真正的自由，','“True freedom')}<br>${T('是选择和谁一起归航。”','is choosing whom to sail home with.”')}</span></div></section><section class="route"><div class="section-title"><p class="eyebrow">THE LONG WAY HOME</p><h2>${T('潮汐航路','The Tidal Route')}</h2><span>${p.completed.length} / 18 ${T('已完成','complete')}</span></div><div class="nodes">${D.stages.map((s,i)=>`<button class="node ${i===p.stage?'current':''} ${i<p.stage?'done':''}" data-act="${i===p.stage?'story':'chapter'}" data-key="${i}" ${i>p.stage?'disabled':''}><span class="node-number">${i<p.stage?'✓':String(i+1).padStart(2,'0')}</span><span><small>${pick(s,'act')}</small><strong>${pick(s,'title')}${i===p.stage&&A.sceneCount(s)>1?` <em class="scene-tag">${p.scene+1}/${A.sceneCount(s)}</em>`:''}</strong><em>${(D.scene(s,i===p.stage?p.scene:0).lanes||s.lanes)} ${T('路',(D.scene(s,i===p.stage?p.scene:0).lanes||s.lanes)===1?'lane':'lanes')} · ${pick(D.objectives[(D.scene(s,i===p.stage?p.scene:0).kind)||s.kind],'name')}${A.sceneCount(s)>1?` · ${A.sceneCount(s)}${T('幕',' scenes')}`:''}</em></span><span>${i===p.stage?'→':i>p.stage?'·':''}</span></button>`).join('')}</div></section></main>`;}
function party(){const st=D.stages[p.stage],sc=st?sceneOf(st):null;return `<main class="camp"><p class="eyebrow">THE ONES WHO STAY</p><h1>${T('同行者','Companions')} <small>${p.party.length} / 5</small></h1><p>${T('击败并理解一个人，才可能与他同行。点击英雄安排出战；小鱼人始终在队伍中。','Defeat someone, then understand them — only then will they walk beside you. Click heroes to field them; Slark always fights.')}</p>${metrics()}${game?`<p class="warning">${T('当前战斗的队伍已锁定。完成或撤退后才能更换。','The party is locked for the current battle. Finish or retreat to change it.')}</p>`:''}<div class="roster">${p.roster.map(k=>`<article class="companion ${p.party.includes(k)?'chosen':''}"><img src="${art(k)}" alt="${esc(name(k))}"><div><small>${p.broken.includes(k)?T('已决裂 · 终局将成为敌人','Severed · returns as an enemy at the end'):k==='slark'?T('每战必选','Fights every battle'):T('羁绊 ','Bond ')+('◆'.repeat(p.loyalty[k]||0))+('◇'.repeat(5-(p.loyalty[k]||0)))}</small><h2>${esc(name(k))}</h2><p>⚔ ${all[k].attack}　♥ ${all[k].health}　◇ ${all[k].armor||0}</p><div>${button('toggle',k==='slark'?T('必定同行','Always travels'):p.party.includes(k)?T('已出战 ✓','Fielded ✓'):T('加入队伍','Join party'),`data-key="${k}" ${game||k==='slark'||p.broken.includes(k)?'disabled':''}`)}${k!=='slark'&&!p.broken.includes(k)?button('break',T('决裂','Sever'),`class="text-danger" data-key="${k}" ${game?'disabled':''}`):''}</div>${p.party.includes(k)&&!game?`<label class="placement-label">${T('初始战线','Opening lane')} <select data-placement="${k}">${Array.from({length:sc?.lanes||st?.lanes||1},(_,l)=>`<option value="${l}" ${(p.placements?.[k]??p.party.indexOf(k))%(sc?.lanes||st?.lanes||1)===l?'selected':''}>${T('第 '+(l+1)+' 路','Lane '+(l+1))}</option>`).join('')}</select></label>`:''}</div></article>`).join('')}</div><section class="camp-shop"><h2>${T('海岸营地','Coastal Camp')}</h2><p>${T('装备会在每场战斗开始时自动给予小鱼人。同一武器槽不会叠加；关内临时增益在休整时消退。','Gear is given to Slark automatically when each battle begins. Weapon slots do not stack; in-stage buffs fade at rest.')}</p>${[['short_sword',T('短剑','Short Sword'),40],['broadsword',T('阔剑','Broadsword'),90],['claymore',T('大剑','Claymore'),160]].map(([k,n,c])=>button('buy',`${p.weapon===k?T('已装备 · ','Equipped · '):''}${n} / ${c} ${T('旅费','supplies')}`,`data-key="${k}" data-price="${c}" ${game||p.gold<c||p.weapon===k?'disabled':''}`)).join(' ')}</section></main>`;}
function cardCopy(c){return K.describe(c,p);}
function cardReward(){return `<main class="camp reward-camp"><p class="eyebrow">CHOOSE YOUR NEXT POSSIBILITY</p><h1>${T('选择一张卡牌','Choose a card')}</h1><p>${T('三选一加入你的牌组，也可以跳过，保持关键牌的抽取概率。奖励已固定，刷新不会重抽。','Take one of three into your deck, or skip to keep your key draws likely. Offers are fixed — refreshing never rerolls.')}</p><div class="reward-cards">${p.cardReward.offers.map(k=>{const c=D.cards.find(c=>c.key===k);return `<article class="deck-card"><img src="${art(c.portrait)}" alt=""><span class="cost">${c.mana}</span><small class="rarity">${c.upgraded?T('已升级 · ','Upgraded · '):''}${RARITIES[c.rarity]||c.rarity}</small><h3>${pick(c,'name')}</h3><p>${cardCopy(c)}</p><footer>${button('claim-card',T('加入牌组','Take it'),`data-key="${k}" class="primary" ${p.deck.length>=30?'disabled':''}`)}</footer></article>`;}).join('')}</div><div class="hero-actions">${button('claim-card',T('跳过 · 不加入卡牌','Skip · take no card'),'data-key="skip"')}${button('deck',T('查看当前牌组','View current deck'))}</div></main>`;}
function deck(){const keys=[...new Set(p.deck)];return `<main class="camp"><p class="eyebrow">BUILD WHAT YOU FIND</p><h1>${T('因果牌组','Causality Deck')} <small>${p.deck.length} ${T('张','cards')}</small></h1><p>${T('战斗胜利后三选一卡，可跳过。每轮抽 5 张，轮末弃置剩余手牌；弃牌堆洗回牌库。更厚的牌组有更多工具，也更难及时抽到核心牌。','Win a battle, pick one of three — or skip. Draw 5 each round and discard the rest; the discard shuffles back. A thicker deck has more tools but slower key draws.')}</p><p>${T('营地每次可升级一张卡（50 旅费），或移除一张卡（35 旅费）；至少保留 8 张。升级只改变所选的一张副本，不会同时升级同名牌。','Each camp upgrades one card (50 supplies) or removes one (35); keep at least 8. Upgrading changes only the chosen copy, never its namesakes.')}</p>${p.cardReward?button('map',T('返回三选一奖励','Back to the pick-one reward'),'class="primary"'):''}<div class="deck-grid">${keys.map(k=>{const c=D.cards.find(c=>c.key===k),tn=p.tuning?.[c.baseKey||k]||0;return `<article class="deck-card"><img src="${art(c.portrait)}" alt=""><span class="cost">${c.mana}</span><h3>${pick(c,'name')} ×${p.deck.filter(v=>v===k).length}${tn?` <small class="tuned">✦${tn}</small>`:''}</h3><p>${cardCopy(c)}</p><footer>${button('upgrade',T('升级一张 · 50','Upgrade one · 50'),`data-key="${k}" ${game||c.upgraded||p.gold<50||p.campActions?.upgrade?'disabled':''}`)}${button('remove',T('移除一张 · 35','Remove one · 35'),`data-key="${k}" ${game||p.gold<35||p.deck.length<=8||p.campActions?.remove?'disabled':''}`)}</footer></article>`;}).join('')}</div><details class="card-pool"><summary>${T('可能遇见的卡牌 · 不可直接领取','Cards you may meet · not claimable here')}</summary><div class="deck-grid">${D.cards.filter(c=>!c.upgraded&&c.key!=='story_scepter'&&!c.foe).map(c=>`<article class="deck-card"><img src="${art(c.portrait)}" alt=""><h3>${pick(c,'name')} · ${c.mana} ${T('魔力','mana')}</h3><p>${cardCopy(c)}</p></article>`).join('')}</div></details></main>`;}
function journal(){const CN={bond:T('守住约定','Kept the promise'),train:T('磨炼技艺','Honed the craft'),power:T('汲取暗月','Drank the dark moon'),temper:T('整备军械','Tempered the kit'),event:T('抉择','A choice')};return `<main class="camp reading"><p class="eyebrow">WHAT THE SEA REMEMBERS</p><h1>${T('潮汐见闻','Tidal Journal')}</h1><p>${T('污名吸引对应追猎者，增加其生命。追求共鸣会更快成长，却会降低同行者羁绊；终幕失去共鸣攻击，并承受共鸣反噬。亲密队友获得额外攻击，约定牌效果更强。','Stigma draws its hunter and feeds their health. Chasing resonance speeds growth but thins companions’ bond; at the finale, resonance attack is lost and bites back. Close companions hit harder, and Bond cards work better.')}</p>${p.journal.length?p.journal.map(j=>j.choice==='event'?`<article class="journal-event"><small>${T('第 '+(j.stage+1)+' 章 · 抉择','Chapter '+(j.stage+1)+' · choice')}</small><h2>${esc(LANG()==='en'&&j.titleEn?j.titleEn:j.title)}</h2><p>${esc(LANG()==='en'&&j.pickEn?j.pickEn:j.pick)}</p><blockquote>${esc(LANG()==='en'&&j.clueEn?j.clueEn:j.clue)}</blockquote></article>`:`<article><small>${T('第 '+(j.stage+1)+' 章','Chapter '+(j.stage+1))} · ${CN[j.choice]||j.choice}</small><h2>${esc(LANG()==='en'&&j.titleEn?j.titleEn:j.title)}</h2><p>${esc(pick(D.stages[j.stage],'outro'))}</p><blockquote>${esc(LANG()==='en'&&j.clueEn?j.clueEn:j.clue)}${j.card&&j.card!=='skip'?` — ${T('得牌','card: ')}${pick(D.cards.find(c=>c.key===j.card)||{},'name')}`:''}</blockquote></article>`).join(''):`<p>${T('你还未离开暗礁。第一份记录，等待一次选择。','You have not left the Reef. The first entry waits on a choice.')}</p>`}<details><summary>${T('关于世界观与素材','About the setting and materials')}</summary><p>${T('本模式为 Dota / Artifact 同人改编；暗礁起源、残月阴谋和剧情技能数值属于原创设定，不代表官方正史。','This mode is a fan-made retelling of Dota / Artifact; the Reef’s origin, the waning-moon conspiracy, and story-skill numbers are original and non-canonical.')}</p><p>${T('新增英雄图像来自 Valve Steam CDN，技能参考 OpenDota 的 Dota 2 数据。原作角色与素材归 Valve 所有。','New hero art comes from the Valve Steam CDN; abilities reference OpenDota Dota 2 data. Original characters and assets belong to Valve.')}</p><a href="assets/campaign/sources.json" target="_blank" rel="noopener">${T('查看素材来源','Art sources')}</a> · <a href="assets/campaign/ability-references.json" target="_blank" rel="noopener">${T('查看技能参考','Ability references')}</a></details></main>`;}
function brief(sc,st){const enemy=all[sc.enemy]||{},rule=RULE_WARN[sc.rule||st.rule],elite=ELITE_WARN[sc.elite||st.elite];return `<section class="brief"><h3>${T('此次旅程','The road ahead')}${sceneBadge(st)}</h3><p>${sc.lanes} ${T('条战线',sc.lanes===1?'lane':'lanes')} · ${pick(D.objectives[sc.kind],'name')}</p><p>${T('限时','Limit')} ${sc.rounds} ${T('轮','rounds')} · ${T('敌方主将','Enemy champion')} ${sc.hp} ${T('生命','HP')} / ${sc.atk} ${T('攻击','ATK')}。${T('全体出战英雄阵亡即失败。','If every fielded hero falls, the stage fails.')}</p>${rule?`<p class="warning">${rule[0]}</p>`:''}${elite?`<p class="warning">${elite[0]}</p>`:''}${sc.pursuit?`<p class="warning">${T('追猎者每轮使用跳刀跨线，落点会提前预告。缴械／眩晕可以打断，也可用闪烁匕首转移被追杀的英雄。','The hunter blinks across lanes each round — the landing is telegraphed. Disarm/stun interrupts it; Blink Dagger can move the hunted hero.')}</p>`:''}${sc.drain?`<p class="warning">${T('暗月抽离：共鸣攻击归零，成长攻击保留 35%；小鱼人受到共鸣 ÷ 3 的初始反噬。','Dark-moon drain: resonance attack is null, growth attack keeps 35%; Slark takes initial backlash of resonance ÷ 3.')}</p>`:''}${sc.kind==='sentry'?`<p class="warning">${T('哨卫规则：每轮一名月纹宫卫上岗；当轮未能击倒，警报立即响彻，潜入失败。攻击牌仍会累积警戒（2 即败）。','Sentry rule: a moon-marked guard posts each round; if it is still standing at round’s end, the alarm rings and the infiltration fails. Attack cards still raise the alarm (2 loses).')}</p>`:''}${sc.foe==='shroud'?`<p class="warning">${T('敌方持有「魅影蔽纱」：每轮一名敌人没入残纱，无法被选为攻击目标。','Foe card — Sisters’ Shroud: each round one enemy slips into the veil and cannot be attacked.')}</p>`:''}${sc.foe==='toll'?`<p class="warning">${T('敌方持有「公会什一税」：每轮抽走一位己方英雄 1 点攻击。','Foe card — Guild Tithe: each round one of your heroes loses 1 attack.')}</p>`:''}</section>`;}
function story(){const st=D.stages[p.stage],sc=sceneOf(st),lines=p.scene>0?(sc.interlude||st.intro):st.intro,ln=lines[Math.min(dialogue,lines.length-1)];return `<main class="story reading"><p class="eyebrow">${pick(st,'act')} / ${pick(st,'place')}${sceneBadge(st)}</p><h1>${pick(st,'title')}</h1>${st.lore&&p.scene===0?`<aside class="lore"><small>${T('旅途背景','LORE')}</small><p>${pick(st,'lore')}</p></aside>`:''}<div class="dialogue"><small>${esc(who(ln[0]))}</small><p>“${esc(line(ln))}”</p><div class="dialogue-progress">${lines.map((_,i)=>`<i class="${i<=dialogue?'lit':''}"></i>`).join('')}</div></div>${brief(sc,st)}<div class="hero-actions">${button(dialogue<lines.length-1?'next':'begin',dialogue<lines.length-1?T('继续对话 →','Continue →'):T('确认队伍，进入战斗','Confirm party — enter battle'),'class="primary"')}${button('party',T('调整队伍','Adjust party'))}</div></main>`;}
function event(ev){return `<main class="story reading"><p class="eyebrow">${T('抉择 · ','A CHOICE · ')}${pick(ev,'place')||''}</p><h1>${pick(ev,'title')}</h1><div class="dialogue event-prompt">${ev.prompt.map(ln=>`<p><small>${esc(who(ln[0]))}</small> “${esc(line(ln))}”</p>`).join('')}</div><div class="choices event-choices">${ev.options.map(o=>`<button class="choice" data-act="event-choice" data-key="${ev.id}:${o.key}"><b>${pick(o,'label')}</b><span>${pick(o,'detail')}</span></button>`).join('')}</div><p class="fine">${T('抉择会写进见闻与存档——每一条路都有代价。','Choices are written into the journal and the save — every road has a price.')}</p></main>`;}
function result(){const st=game.stage(),sc=game.scene(),won=game.s.winner===0,last=game.s.scene>=A.sceneCount(st)-1;
 if(won&&!last){const nsc=st.scenes[game.s.scene+1];return `<div class="veil"><section class="result"><p class="eyebrow">SCENE CLEAR</p><h1>${T('此幕落幕','The scene closes')}</h1><p>${esc(pick(sc,'lore')||'')}</p>${game.s.contracts?`<p>${T('悬赏契约结算：旅费 +','Bounty contracts settle: supplies +')}${game.s.contracts}</p>`:''}<p>${T('下一幕：','Next scene: ')}${esc(pick({title:nsc.title||st.title,titleEn:nsc.titleEn||st.titleEn},'title'))} — ${pick(D.objectives[nsc.kind],'name')} · ${nsc.lanes} ${T('路',nsc.lanes===1?'lane':'lanes')}</p><div class="hero-actions">${button('next-scene',T('进入下一幕 →','To the next scene →'),'class="primary"')}</div></section></div>`;}
 return `<div class="veil"><section class="result"><p class="eyebrow">${won?'THE TIDE REMEMBERS':'THE SEA OFFERS ANOTHER CHANCE'}</p><h1>${won?T('潮汐向前','The Tide Moves On'):T('暂别此岸','Leave this Shore, for Now')}</h1><p>${won?pick(st,'outro'):esc(game.s.log.at(-1)?.text)}</p>${won?`<blockquote>${pick(st,'clue')}</blockquote><p>${T('成长生命 +1，旅费 +35','Growth +1 health, supplies +35')}${game.s.contracts?`，${T('悬赏契约','bounty contracts')} +${game.s.contracts}`:''}${st.grant?`；${T('获得卡牌','card gained: ')}${pick(D.cards.find(c=>c.key===st.grant)||{},'name')}`:''}${st.recruit?'；'+name(st.recruit)+(st.bonusRecruit?'、'+name(st.bonusRecruit):'')+T(' 可加入队伍',' may join the party'):''}${T('。选择一项永久改变：','. Choose one permanent change:')}</p><div class="choices">${button('reward',`<b>${T('守住约定','Keep the Promise')}</b><span>${T('同行羁绊 +1<br>格挡牌治疗 +1（上限 4）','Companion bond +1<br>Guard card heal +1 (max 4)')}</span>`,'data-key="bond"')}${button('reward',`<b>${T('磨炼技艺','Hone the Craft')}</b><span>${T('成长攻击 +0.5<br>能量转移伤害 +1（上限 4）','Growth attack +0.5<br>Essence Shift damage +1 (max 4)')}</span>`,'data-key="train"')}${button('reward',`<b>${T('汲取暗月','Drink the Dark Moon')}</b><span>${T('成长攻击 +1 / 额外共鸣 +2<br>污名 +1，同行羁绊 −1','Growth attack +1 / resonance +2<br>Stigma +1, companion bond −1')}</span>`,'data-key="power"')}${button('reward',`<b>${T('整备军械','Temper the Kit')}</b><span>${T('历练 +1（同伴生命更厚）<br>牌组中一张牌核心数值 +1','Drill +1 (companions hardier)<br>One deck card gains +1 to its core number')}</span>`,'data-key="temper"')}</div>`:`<p>${T('关前成长保留，可调整队伍、牌组后重试当前一幕。神杖一旦使用，不会因失败返还。','Growth earned earlier is kept; adjust party and deck, then retry the current scene. A spent Scepter is never returned by defeat.')}</p>${button('retry',T('回到营地','Back to camp'),'class="primary"')}`}</section></div>`;}
function ending(){const loyal=p.roster.filter(k=>k!=='slark'&&!p.broken.includes(k)&&p.loyalty[k]>=3).length;return `<main class="story reading"><p class="eyebrow">EPILOGUE / ${loyal>=3?T('归航','Homeward'):p.broken.length?T('残岸','Sundered Shore'):T('微光','Emberlight')}</p><h1>${loyal>=3?T('海的另一边','The Far Side of the Sea'):p.broken.length?T('潮水记得所有名字','The Tide Remembers Every Name'):T('一盏仍亮的灯','One Lamp Still Burning')}</h1><p class="ending-copy">${loyal>=3?T('山心回到山上，蛛丝补好了村子的帆。斯拉达不再守门，拉比克学会了先问再借。小鱼人没有成为新的锁；他和同行者轮流守望潮汐，第一次拥有了可以离开的家。','The mountain heart went home; spider-silk patched the village sails. Slardar guards no door, and Rubick learned to ask before borrowing. The fish-person became no new lock — he and his companions take turns watching the tide, and for the first time he has a home he is free to leave.'):p.broken.length?T('裂缝合拢了。有些名字却永远留在了桥上。小鱼人把潮汐刃放回海中，用余生寻找那些无法被力量偿还的答案。','The rift has closed. Some names stayed on the bridge forever. The fish-person laid the tideblade back into the sea, and spends his remaining days seeking answers no strength can repay.'):T('暗月退去，海岸还有一盏灯。小鱼人坐在灯下，给曾经同行的人写信。自由来得很慢，但这一次，他愿意等。','The dark moon ebbs; one lamp still burns on the shore. Beneath it, the fish-person writes letters to those who once walked beside him. Freedom comes slowly — but this time, he is willing to wait.')}</p>${metrics()}<p>${loyal} ${T('位深厚羁绊','deep bonds')} · ${p.broken.length} ${T('位决裂同伴','severed companions')} · ${p.resonance} ${T('暗月共鸣','dark-moon resonance')}</p>${button('journal',T('重读旅程','Reread the journey'),'class="primary"')}${button('restart',T('开启新的旅程','Begin a new journey'))}</main>`;}
function render(){root.innerHTML=top()+(message?`<p class="warning">${esc(message)}</p>`:'')+({map,party,deck,journal,story}[view]||map)()+(confirmKey?`<div class="veil"><section class="result"><h2>${confirmKey==='restart'?T('开启新的旅程？','Begin a new journey?'):confirmKey==='retreat'?T('撤退到营地？','Retreat to camp?'):T('与 ','Sever the bond with ')+esc(name(confirmKey))+(confirmKey==='restart'||confirmKey==='retreat'?'':T(' 决裂？','?'))}</h2><p>${confirmKey==='restart'?T('将覆盖当前剧情存档，经典对战不受影响。建议先导出备份。','This overwrites the campaign save; Classic matches are untouched. Export a backup first.'):confirmKey==='retreat'?T('本关进度会重置，永久成长保留。','Stage progress resets; permanent growth is kept.'):T('获得 50 旅费与 1 攻击、2 共鸣，但这位同伴将永久离队，并在终局以强化幻影回归。','Gain 50 supplies, +1 attack, +2 resonance — but this companion leaves forever, returning at the finale as a stronger shade.')}</p>${button('confirm',T('确认','Confirm'),'class="primary"')}${button('cancel',T('返回','Back'))}</section></div>`:'');}
root.addEventListener('click',async e=>{const b=e.target.closest('[data-act]');if(!b||b.disabled||busy)return;try{await sound.start();if(busy)return;const act=b.dataset.act,k=b.dataset.key;if(['map','party','deck','journal'].includes(act)){view=act;}else switch(act){
 case 'audio':sound.enabled=!sound.enabled;sound.setVolumes();break;
 case 'story':if(game){location.href='campaign-battle.html';return;}dialogue=0;view='story';break;
 case 'next':dialogue++;break;
 case 'begin':game=new A.CampaignGame(base);game.begin(p);save();location.href='campaign-battle.html';return;
 case 'resume':location.href='campaign-battle.html';return;
 case 'next-scene':A.advanceScene(p,game);game=null;dialogue=0;view='story';save();break;
 case 'event-choice':{const [id,key]=k.split(':');A.applyChoice(p,id,key);save();}break;
 case 'toggle':A.chooseParty(p,k);save();break;
 case 'break':confirmKey=k;break;
 case 'restart':confirmKey='restart';break;
 case 'retreat':confirmKey='retreat';break;
 case 'cancel':confirmKey=null;break;
 case 'confirm':if(confirmKey==='restart'){p=A.fresh();game=null;view='map';}else if(confirmKey==='retreat'){game=null;view='party';sound.setScene('menu');}else A.abandon(p,confirmKey);confirmKey=null;save();break;
 case 'buy':if(game)throw Error(T('战斗中无法购买','Cannot buy during battle'));{const price={short_sword:40,broadsword:90,claymore:160}[k];if(!price||p.gold<price)throw Error(T('旅费不足','Not enough supplies'));p.gold-=price;p.weapon=k;save();sound.play('buy');}break;
 case 'claim-card':K.claim(p,k);save();view='map';break;
 case 'upgrade':K.upgrade(p,k);save();break;
 case 'remove':K.remove(p,k);save();break;
 case 'reward':A.reward(p,game,k);game=null;view='map';sound.setScene('menu');save();break;
 case 'retry':game=null;view='party';sound.setScene('menu');save();break;
 case 'export':{const url=URL.createObjectURL(new Blob([JSON.stringify(p,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='dark-moon-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 case 'chapter':notify(pick(D.stages[Number(k)],'clue'));return;
 }render();}catch(err){busy=false;notify(err.message);}});
root.addEventListener('change',async e=>{if(e.target.dataset.placement){p.placements||={};p.placements[e.target.dataset.placement]=Number(e.target.value);save();return;}if(e.target.id!=='import')return;try{const raw=JSON.parse(await e.target.files[0].text());K.migrate(raw);if(!A.valid(raw))throw Error(T('不是有效的暗月剧情存档','Not a valid Dark Moon save'));if(!window.confirm(T('导入将替换当前剧情进度，是否继续？','Importing replaces current campaign progress. Continue?')))return;p=raw;game=null;if(p.battle){game=new A.CampaignGame(base);game.s=p.battle;}view='map';message='';save();render();}catch(err){notify(T('导入失败：','Import failed: ')+err.message);}});
document.addEventListener('visibilitychange',()=>sound.visibility(document.hidden));
I.onChange(()=>render());
render();
})();
